import{z as i,x as p,o as r,c as B,q as E,j as o,D as e,d as t,s as A,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"自回归图像生成","description":"","frontmatter":{"title":"自回归图像生成","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autoregressive-image-gen.md","filePath":"llm/autoregressive-image-gen.md","lastUpdated":1791063341000}'),d={name:"llm/autoregressive-image-gen.md"};function m(h,a,f,T,D,u){const s=p("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="自回归图像生成" tabindex="-1">自回归图像生成 <a class="header-anchor" href="#自回归图像生成" aria-label="Permalink to &quot;自回归图像生成&quot;">​</a></h1><div class="epigraph"><p>把图变成离散码序列之后，图像生成就是语言模型：预测下一个下标，再交给解码器变回像素。</p><footer>—— Esser 等 VQGAN 上的 Transformer；Ramesh 等 DALL·E；Yu 等 Parti</footer></div><p><a href="/llm/cfg-image">上一课</a>在连续潜空间里用 CFG 拉条件。<a href="/llm/vqgan">VQGAN</a> 已给出可感知的码本。缺口是：在这些离散视觉 token 上做 next-token，与文本 LLM 同构。后课 VAR 默认 raster 扫描不是唯一的分解顺序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>像素 softmax 不可行。量化后长度为 \\(hw\\) 的码序列，因果 Transformer 建模 \\(p(k_{1:hw})\\)。DALL·E 用 dVAE 码 + 文本条件；Parti 把这条路做到更大的编码器–解码器；VQGAN 论文的后半是码上的 GPT。上限仍是 tokenizer 重构天花板：LM 完美，图也回不到比解码器更好。</p><p><span class="marginnote">像素为什么不能直接当 token：RGB 每通道 256 档，一个像素就有 \\(256^3\\approx 1670\\) 万种取值，softmax 要在千万维上打分。量化成码本（比如 1024 个码）之后，每步只是从 1024 个选项里挑一个——词表规模才回到 LLM 熟悉的量级。</span></p><p>扫描顺序默认 raster。竖直邻居在序列上相距一行宽度，与<a href="/llm/2d-rope">2D RoPE</a> 之前理解侧的一维编号是同一扭曲——生成侧会表现为纵向结构难、局部纹理靠码本。</p><p><span class="marginnote">条件可以是文本 token 前缀，不必是 <a href="/llm/llava-projector">LLaVA 投影器</a> 那种连续视觉前缀。理解连续、生成离散，正是后课统一模型要缝的缝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先训或冻 tokenizer，再在码上做语言建模，文本为前缀或交叉注意力。采样温度、top-k 与扩散 CFG 不同旋钮：过低温会重复图案。验收：FID + 文本遵守 + 文字可读；不要用 <a href="/llm/clip">CLIP</a> 图文检索单独选 AR 超参。</p>',10)),(r(),o(n,null,{default:e(()=>[A(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20AR%5B%22%E5%9B%A0%E6%9E%9C%20Transformer%22%5D%0A%20%20AR%20--%3E%20IDS%5B%22%E7%A6%BB%E6%95%A3%E7%A0%81%E5%BA%8F%E5%88%97%22%5D%0A%20%20IDS%20--%3E%20DEC%5B%22VQ%20%E8%A7%A3%E7%A0%81%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"似然在码上分解为逐步条件。错误会沿 raster 传播：早错一个码，后面整行跟着歪。这与扩散每步改整张潜图不同。因此 AR 对全局布局敏感于开头码，扩散对噪声日程敏感。",-1)),(r(),o(n,null,{default:e(()=>[A(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20T1%5B%22%E7%A0%811%20%E5%B7%A6%E4%B8%8A%E8%A7%92%22%5D%20--%3E%20T2%5B%22%E7%A0%812%20%E9%A1%BA%E7%9D%80%20raster%20%E8%B5%B0%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E7%A0%813%20%E7%AC%AC%E4%B8%80%E8%A1%8C%E5%B0%BE%22%5D%0A%20%20T3%20--%3E%20T4%5B%22%E7%A0%814%20%E7%AC%AC%E4%BA%8C%E8%A1%8C%E5%A4%B4%22%5D%0A%20%20T4%20--%3E%20ERR%5B%22%E7%A0%814%20%E9%A2%84%E6%B5%8B%E5%87%BA%E9%94%99%22%5D%0A%20%20ERR%20--%3E%20T5%5B%22%E5%90%8E%E7%BB%AD%E7%A0%81%E6%8C%89%E9%94%99%E8%AF%AF%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BB%AD%E5%86%99%22%5D%0A%20%20T5%20--%3E%20IMG%5B%22%E6%95%B4%E5%9B%BE%E5%B8%83%E5%B1%80%E8%A2%AB%E5%B8%A6%E6%AD%AA%E4%B8%94%E6%97%A0%E6%B3%95%E5%9B%9E%E5%A4%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">直觉类比：AR 画图像逐字写小说——开头几句定下题材，后面每句只能顺着写，错了不能回头重涂；扩散更像画家先铺满整幅再反复修饰，每一步都能全局调整。所以 AR 图的开头几个码责任极大，往往对应天空、背景这类决定布局的区域。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>序列长度随分辨率平方涨，双向纹理要靠深注意力补。下一课把「下一步」改成下一尺度，而不是下一格。</p><p><span class="marginnote">「长度平方涨」代个数：256×256 的图按 16×16 像素压成一个码，是 16×16=256 个码，还在 LLM 舒适区；512×512 就是 1024 个码，1024×1024 是 4096 个码。注意力开销随长度平方涨，高分辨率的生成延迟立刻肉眼可见。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离散码上的 AR 让图像生成与 LLM 同构。</li><li>质量受 VQ 天花板与扫描顺序双重约束。</li><li>与连续扩散是两条接口，不是同一损失。</li><li>出处：VQGAN Transformer；DALL·E；Parti。</li></ul>',6))])}const g=i(d,[["render",m]]);export{_ as __pageData,g as default};
